create or replace function public.create_tournament_atomic(p_name text,p_description text,p_format text,p_max_players smallint,p_starts_at timestamptz,p_visibility text,p_entry_information text,p_game_title text,p_prize_pool numeric,p_teams jsonb,p_fixtures jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare t uuid; row jsonb; f jsonb; home_id uuid; away_id uuid; builtin_id text; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if not exists (select 1 from public.profiles where id=auth.uid()) then raise exception 'Your MatchUp profile is not ready yet. Please refresh and try again.'; end if; if char_length(btrim(p_name))<3 then raise exception 'Tournament name must be at least 3 characters.'; end if; if p_format not in ('league','round_robin','group_stage','knockout','single_elimination','double_elimination','groups_knockout') then raise exception 'Unsupported tournament format.'; end if; if p_visibility not in ('public','private','invite_only') then raise exception 'Unsupported tournament visibility.'; end if; if p_max_players<2 or p_max_players>128 then raise exception 'Maximum teams must be between 2 and 128.'; end if; if p_prize_pool is null or p_prize_pool<0 then raise exception 'Prize pool cannot be negative.'; end if; if jsonb_array_length(coalesce(p_teams,'[]'::jsonb))<2 or jsonb_array_length(p_teams)>128 then raise exception 'Tournament must have between 2 and 128 teams.'; end if; insert into public.tournaments(organizer_id,name,description,format,max_players,starts_at,visibility,entry_information,game_title,prize_pool) values(auth.uid(),btrim(p_name),coalesce(p_description,''),p_format,p_max_players,p_starts_at,p_visibility,coalesce(p_entry_information,''),coalesce(nullif(btrim(p_game_title),''),'Football'),p_prize_pool) returning id into t; for row in select value from jsonb_array_elements(p_teams) loop builtin_id:=nullif(row->>'builtin_team_id',''); if builtin_id is not null and not exists(select 1 from public.football_teams ft where ft.id=builtin_id) then builtin_id:=null; end if; insert into public.tournament_teams(tournament_id,builtin_team_id,team_name,short_name,country,league,city,crest_path,seed) values(t,builtin_id,btrim(row->>'team_name'),btrim(row->>'short_name'),coalesce(row->>'country',''),coalesce(row->>'league',''),coalesce(row->>'city',''),nullif(row->>'crest_path',''),(row->>'seed')::smallint); end loop; for f in select value from jsonb_array_elements(coalesce(p_fixtures,'[]'::jsonb)) loop select id into home_id from public.tournament_teams where tournament_id=t and seed=(f->>'home_seed')::smallint limit 1; select id into away_id from public.tournament_teams where tournament_id=t and seed=(f->>'away_seed')::smallint limit 1; if home_id is null or away_id is null then continue; end if; insert into public.fixtures(tournament_id,round_number,position,round_label,group_name,home_team_id,away_team_id,status) values(t,(f->>'round_number')::smallint,(f->>'position')::smallint,coalesce(f->>'round_label',''),nullif(f->>'group_name',''),home_id,away_id,'pending'); end loop; return t; end; $$;

create or replace function public.record_media_download(p_post_id uuid,p_media_type text) returns void language plpgsql security definer set search_path=public as $$ declare owner uuid; label text; source_path text; post_text text; thumb text; begin if auth.uid() is null then raise exception 'Not authenticated'; end if; if p_media_type not in ('image','video') then raise exception 'Invalid media type'; end if; select author_id,body into owner,post_text from public.posts where id=p_post_id; if owner is null then raise exception 'Post not found'; end if; select storage_path into source_path from public.post_media where post_id=p_post_id and media_type=p_media_type order by position asc limit 1; if source_path is not null then thumb:='https://mapnzdswhycybzintiva.supabase.co/storage/v1/object/public/feed-media/'||source_path; end if; label:=case when p_media_type='video' then 'video' else 'image' end; insert into public.notifications(recipient_id,kind,payload) values(auth.uid(),'media_downloaded',jsonb_build_object('message','You downloaded this '||label||' from a MatchUp post.','entity_type','post','entity_id',p_post_id::text,'media_type',p_media_type,'thumbnail',thumb,'post_body',coalesce(post_text,''),'href','/feeds?post='||p_post_id::text)); end; $$;
